(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.STS_WORKSPACE_PAGES=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(l,en,bn)=>l==='bn'?bn:en;
const titles={rotations:['Rotation plans','ফসল আবর্তনের পরিকল্পনা'],compare:['Compare plans','পরিকল্পনা তুলনা'],simulator:['What-if studio','পরিস্থিতি বদলে দেখুন'],climate:['Climate insights','জলবায়ুর তথ্য'],saved:['Saved plan','সংরক্ষিত পরিকল্পনা'],methodology:['Data & methodology','তথ্য ও পদ্ধতি']};
function intro(route,lang){const title=titles[route]||['Your results','আপনার ফলাফল'];return `<header class="result-page-intro"><div><p class="result-eyebrow">SOIL TO STARS · FIELD STUDIO</p><h1 tabindex="-1" id="workspace-page-title">${esc(title[lang==='bn'?1:0])}</h1></div><a href="/">${t(lang,'Back to homepage','মূল পাতায় ফিরুন')} ↗</a></header>`;}
function methodology(lang){return `<section class="result-card"><h2>${t(lang,'From observations to a decision','পর্যবেক্ষণ থেকে সিদ্ধান্ত')}</h2><ol class="method-steps"><li><b>${t(lang,'Your field knowledge','আপনার জমির তথ্য')}</b><p>${t(lang,'Location, current crop, availability, history, usual rotation, water access and priorities. Stored in this browser.','অবস্থান, বর্তমান ফসল, সময়, ইতিহাস, সাধারণ আবর্তন, পানি ও অগ্রাধিকার। এই ব্রাউজারে থাকে।')}</p></li><li><b>NASA POWER · 2001–2025</b><p>${t(lang,'T2M: 2m air temperature. PRECTOTCORR: corrected precipitation. Local annual summaries are available for representative district grid points. They are not field or district averages.','T2M: দুই মিটার উচ্চতায় বায়ুর তাপমাত্রা। PRECTOTCORR: সংশোধিত বৃষ্টিপাত। স্থানীয় বার্ষিক সারাংশ জেলার প্রতিনিধি গ্রিড পয়েন্টের জন্য; জমি বা জেলার গড় নয়।')}</p></li><li><b>${t(lang,'Crop evidence','ফসলের প্রমাণ')}</b><p>${t(lang,'BAMIS calendars and regional crop evidence have been collected. Active suitability thresholds, stages, operation durations and rotation rules still need validation before scoring.','বামিস ক্যালেন্ডার ও আঞ্চলিক ফসলের তথ্য সংগ্রহ করা হয়েছে। স্কোরিংয়ের আগে উপযোগিতা, পর্যায়, সময় ও আবর্তনের নিয়ম যাচাই করা বাকি।')}</p></li><li><b>${t(lang,'Deterministic comparison — pending','নির্দিষ্ট নিয়মে তুলনা — বাকি')}</b><p>${t(lang,'Compare usual practice with two distinct supported alternatives on one shared period. Each complete alternative has three future crops, including preparation, harvest and field-clearance time.','একই সময়সীমায় সাধারণ চাষের সাথে দুটি পৃথক সমর্থিত বিকল্প তুলনা করা হবে। প্রতিটি পূর্ণ বিকল্পে ভবিষ্যতের তিনটি ফসল এবং প্রস্তুতি, ফসল তোলা ও জমি খালি করার সময় থাকবে।')}</p></li></ol></section><section class="result-card"><h2>${t(lang,'How to read the evidence','প্রমাণ কীভাবে পড়বেন')}</h2><dl><dt>${t(lang,'Available now','এখন উপলব্ধ')}</dt><dd>${t(lang,'Local historical weather charts, source identities, district selection and input validation.','স্থানীয় ঐতিহাসিক আবহাওয়ার চার্ট, উৎসের পরিচয়, জেলা নির্বাচন ও ইনপুট যাচাই।')}</dd><dt>${t(lang,'Not yet connected','এখনো সংযুক্ত নয়')}</dt><dd>${t(lang,'Field-specific crop suggestions and suitability scores require more local agronomy evidence. Historical warning checks cover only matching source references.','জমির জন্য নতুন ফসলের পরামর্শ ও উপযোগিতা স্কোর দিতে আরও স্থানীয় কৃষিতথ্য দরকার। মিল থাকা উৎসের জন্যই পুরোনো আবহাওয়ার সতর্কতা যাচাই করা হয়।')}</dd><dt>${t(lang,'Limits','সীমাবদ্ধতা')}</dt><dd>${t(lang,'No live diagnosis, future-weather guarantee, yield/profit forecast or fertilizer prescription. Missing evidence stays unknown. Historical warning exceedances are not crop damage estimates.','সরাসরি রোগ নির্ণয়, ভবিষ্যৎ আবহাওয়ার নিশ্চয়তা, ফলন/লাভের পূর্বাভাস বা সার ব্যবস্থাপত্র নেই। অনুপস্থিত প্রমাণ অজানা থাকে। নমুনা পরিকল্পনা কৃষি পরামর্শ নয়।')}</dd></dl><p><a href="https://power.larc.nasa.gov/docs/services/api/temporal/daily/" target="_blank" rel="noopener">NASA POWER ↗</a> · <a href="https://www.bamis.gov.bd/" target="_blank" rel="noopener">BAMIS ↗</a></p></section>`;}
function simulator(request,lang,scenario){
 const r=scenario?.request||request;
 return `<section class="result-card"><h2>${t(lang,'Change one assumption at a time','একবারে একটি অনুমান বদলান')}</h2><p>${t(lang,'Try a different water or priority answer. The report records your choices. Crop rankings and water demand calculations are currently unavailable.','সেচ বা অগ্রাধিকারের অন্য উত্তর দিয়ে দেখুন। রিপোর্টে আপনার পছন্দ দেখা যাবে। ফসলের ক্রম ও পানির চাহিদার হিসাব এখন অনুপলব্ধ।')}</p><form id="whatif-form"><label for="whatif-water">${t(lang,'Water access','পানির সুবিধা')}</label><select id="whatif-water" ${!r?'disabled':''}>${[['rainfed','Rainfed','বৃষ্টিনির্ভর'],['limited','Limited irrigation','সীমিত সেচ'],['reliable','Reliable irrigation','নির্ভরযোগ্য সেচ']].map(([v,en,bn])=>`<option value="${v}" ${r?.irrigation?.access===v?'selected':''}>${t(lang,en,bn)}</option>`).join('')}</select><div id="whatif-irrigation-fields" ${r?.irrigation?.access==='rainfed'||!r?'hidden':''}><label for="whatif-seasonal-limitations">${t(lang,'Seasonal irrigation limits','মৌসুমি সেচের সীমাবদ্ধতা')}</label><select id="whatif-seasonal-limitations"><option value="">${t(lang,'Choose an answer','উত্তর বেছে নিন')}</option><option value="none" ${r?.irrigation?.seasonal_limitations==='none'?'selected':''}>${t(lang,'No seasonal limitations reported','মৌসুমি সীমাবদ্ধতা নেই বলে জানাচ্ছি')}</option><option value="seasonal" ${r?.irrigation?.seasonal_limitations==='seasonal'?'selected':''}>${t(lang,'Limited in specific seasons','নির্দিষ্ট মৌসুমে সীমিত')}</option></select><fieldset id="whatif-limited-seasons" ${r?.irrigation?.seasonal_limitations==='seasonal'?'':'hidden'}><legend>${t(lang,'Seasons with limited irrigation','সেচ সীমিত থাকে যে মৌসুমে')}</legend>${[['kharif_1','Kharif I','খরিফ–১'],['kharif_2','Kharif II','খরিফ–২'],['rabi','Rabi','রবি']].map(([id,en,bn])=>`<label><input type="checkbox" data-whatif-season value="${id}" ${(r?.irrigation?.limited_seasons||[]).includes(id)?'checked':''}> ${t(lang,en,bn)}</label>`).join('')}</fieldset></div><label for="whatif-priority">${t(lang,'Priority','অগ্রাধিকার')}</label><select id="whatif-priority" ${!r?'disabled':''}>${[['water','Save water','পানি সাশ্রয়'],['soil_rotation','Rotation diversity','আবর্তনের বৈচিত্র্য'],['balanced','Balanced','ভারসাম্যপূর্ণ']].map(([v,en,bn])=>`<option value="${v}" ${r?.priority===v?'selected':''}>${t(lang,en,bn)}</option>`).join('')}</select><div class="result-actions"><button type="button" data-result-action="run-scenario" ${!r||scenario?.state==='loading'?'disabled':''}>${t(lang,'Preview these answers','এই উত্তরগুলো দেখুন')}</button><button type="button" data-result-action="reset-scenario">${t(lang,'Reset scenario','পরিস্থিতি রিসেট')}</button><a href="#profile">${t(lang,'Change crop or dates in field inputs','জমির তথ্যে ফসল বা তারিখ বদলান')}</a></div></form><p role="status">${scenario?.state==='loading'?t(lang,'Evaluating…','মূল্যায়ন হচ্ছে…'):scenario?.response?esc(scenario.response.reason||t(lang,'Scenario response supplied; review its status and evidence below.','পরিস্থিতির উত্তর এসেছে; নিচে অবস্থা ও প্রমাণ দেখুন।')):t(lang,r?'Evaluation requires the same scientific backend as your original plan.':'Submit your field inputs to enable scenario controls.',r?'মূল পরিকল্পনার একই বৈজ্ঞানিক ব্যাকএন্ডে মূল্যায়ন হবে।':'পরিস্থিতির নিয়ন্ত্রণ চালু করতে জমির তথ্য জমা দিন।')}</p></section>`;
}
function render(route,ctx){
 const {ui,language:l='en',active,request,selectedPlan,metric,weather,bundle,saved,scenario}=ctx;
 const response=active?.response,has=response&&['complete','incomplete'].includes(response.status);
 let content='';
 if(route==='methodology')content=methodology(l)+(ui.trialPanel?.(l)||'');
 if(route==='climate')content=`<section class="result-card"><h2>${t(l,'How has the weather shifted?','আবহাওয়া কীভাবে বদলেছে?')}</h2><p>${t(l,'Explore 25 years of archived NASA POWER temperature and rainfall. Select a district; compare two equal ten-year periods.','নাসা পাওয়ারের সংরক্ষিত ২৫ বছরের তাপমাত্রা ও বৃষ্টিপাত দেখুন। জেলা বেছে সমান দশ বছরের দুই সময়ের তুলনা করুন।')}</p>${weather.render(bundle,ctx.district,metric,l,ui.chart)}<a href="/#weather-story">${t(l,'Explore the scrolling weather story','স্ক্রল করে আবহাওয়ার গল্প দেখুন')} ↗</a></section>`;
 if(route==='compare'||route==='rotations'){
   const plan=response?.alternatives?.find(p=>p.plan_id===selectedPlan)||response?.alternatives?.[0];
   content=has ? ui.comparison(response,l,selectedPlan,'#overview',route==='compare') : `<section class="result-card">
     <h2>${t(l,'Start with your field','আপনার জমি দিয়ে শুরু করুন')}</h2>
     <p>${t(l,'Enter your field details to see your usual crop order and any crop calendars we have for your area.','আপনার সাধারণ ফসলের ক্রম ও এলাকার উপলব্ধ ফসলের ক্যালেন্ডার দেখতে জমির তথ্য দিন।')}</p>
     <a href="#profile">${t(l,'Set up your field','জমির তথ্য দিন')}</a>
   </section>`;
   if(request&&!has)content=active?.state==='loading' ? `<p role="status">${t(l,'Preparing your field report…','জমির রিপোর্ট তৈরি হচ্ছে…')}</p>` : `<section class="result-card"><h2>${t(l,'Generate your field report','জমির রিপোর্ট তৈরি করুন')}</h2><button type="button" data-result-action="request-planning">${t(l,'Generate report','রিপোর্ট তৈরি করুন')}</button> <a href="#overview">${t(l,'Open your results','ফলাফল দেখুন')}</a></section>`;
   if(route==='rotations'&&(plan||active?.fixture_id))content+=ui.operationTimeline(plan,l);
   if(route==='compare'&&has)content+=`<details class="result-card result-expand"><summary>${t(l,'Why field planning is limited','জমির পরিকল্পনা সীমিত কেন')}</summary>${ui.evidencePanel(response,l)}</details>`;
 }
 if(route==='simulator')content=simulator(active?.request||request,l,scenario)+(scenario?.response&&['complete','incomplete'].includes(scenario.response.status)?ui.comparison(scenario.response,l,null)+(ui.evidenceProfile?ui.evidenceProfile(scenario.response,l):''):'');
 if(route==='saved')content=saved?`<section class="result-card"><h2>${esc(saved.label||t(l,'Saved plan snapshot','সংরক্ষিত পরিকল্পনার কপি'))}</h2><p>${t(l,'Saved in this browser at','এই ব্রাউজারে সংরক্ষিত হয়েছে')} ${esc(saved.saved_at)}</p><p>${saved.example?t(l,'DEVELOPMENT EXAMPLE · not agricultural advice','ডেভেলপমেন্ট নমুনা · কৃষি পরামর্শ নয়'):t(l,'Snapshot of the supplied result; not a fresh assessment.','সরবরাহকৃত ফলাফলের কপি; নতুন মূল্যায়ন নয়।')}</p><p>${JSON.stringify(saved.data.request)!==JSON.stringify(request)?t(l,'This snapshot may use different field inputs. Review its original inputs before using it.','এই কপির জমির তথ্য আলাদা হতে পারে। ব্যবহারের আগে মূল তথ্য দেখুন।'):''}</p><div class="result-actions"><button data-result-action="download-saved">${t(l,'Download saved JSON','সংরক্ষিত JSON ডাউনলোড')}</button><button data-result-action="remove-snapshot">${t(l,'Remove saved snapshot','সংরক্ষিত কপি সরান')}</button><button data-result-action="print">${t(l,'Print','প্রিন্ট')}</button></div></section>${ui.genuineSummary(saved.data.request,l,saved.data.response.status)}${saved.plan_id==='evidence-report'?ui.evidenceProfile(saved.data.response,l):ui.operationTimeline(saved.data.response.alternatives?.find(p=>p.plan_id===saved.plan_id),l)}`:`<section class="result-card"><h2>${t(l,'No plan saved yet','কোনো পরিকল্পনা সংরক্ষিত নেই')}</h2><p>${t(l,'Generate an evidence report, then choose Save evidence report in Overview. Supported future plans can also be saved when available.','রিপোর্ট তৈরি করে সারাংশ পাতায় প্রমাণের রিপোর্ট সংরক্ষণ বেছে নিন। সমর্থিত ভবিষ্যৎ পরিকল্পনাও উপলব্ধ হলে সংরক্ষণ করা যাবে।')}</p><a href="#rotations">${t(l,'Explore rotation plans','ফসল আবর্তন দেখুন')} ↗</a></section>`;
 return `<div class="result-page" data-no-translate>${intro(route,l)}${active?.fixture_id?`<aside class="fixture-banner">${t(l,'DEVELOPMENT FIXTURE · NOT SCIENTIFIC ADVICE','ডেভেলপমেন্ট ফিক্সচার · বৈজ্ঞানিক পরামর্শ নয়')} <button data-result-action="exit-fixture">${t(l,'Return to field inputs','জমির তথ্যে ফিরুন')}</button></aside>`:''}${content}</div>`;
}
return {render,titles};
});
